function suggestLine(r,learned){const nm=normAr(r.name+' '+r.nameEn);const sc={};const add=(id,v)=>{sc[id]=(sc[id]||0)+v};
 for(const [id,ws] of SYNN)for(const w of ws)if(w&&nm.includes(w))add(id,4+Math.min(w.length,20)/4);
 const toks=nm.split(' ').filter(t=>t.length>2);for(const [id,ts] of ACCTOK)for(const t of toks)if(ts.some(x=>(' '+x+' ').includes(' '+t+' ')))add(id,1);
 if(learned){for(let L_=Math.min(r.code.length-1,6);L_>=2;L_--){const p=r.code.slice(0,L_);const g=learned.get(p);if(g){const [best,cnt,tot]=g;if(cnt/tot>=.6)add(best,3+L_*0.8);break}}}
 /* contra/sign hints: an accumulated-depreciation name with a credit balance still belongs to PPE; "مخصص" with debit balance in P&L → ECL/provision expense */
 if(/مجمع|accumulated/.test(nm)&&sc.depx)sc.depx-=3;if(/(مخصص|provision)/.test(nm)&&r.cb>0&&!/(مستحق|payable)/.test(nm))add('eclx',2);
 const best=Object.entries(sc).sort((a,b)=>b[1]-a[1]);if(!best.length)return null;const [id,s]=best[0];const s2=best[1]?best[1][1]:0;return{id,score:s,conf:s>=7&&s-s2>=2?'H':s>=4?'M':'L'}}
function learnedPrefixes(){const m=new Map();const add=(code,line)=>{for(let L_=2;L_<=Math.min(code.length-1,6);L_++){const p=code.slice(0,L_);let x=m.get(p);if(!x){x={};m.set(p,x)}x[line]=(x[line]||0)+1}};
 for(const r of TBSTORE.rows){const l=tbMapOf(r.code);if(l)add(r.code,l)}const out=new Map();for(const [p,x] of m){const e=Object.entries(x).sort((a,b)=>b[1]-a[1]);const tot=e.reduce((s,y)=>s+y[1],0);out.set(p,[e[0][0],e[0][1],tot])}return out}
