 <label>تصفية<select class="sel" data-tbq="flag">${[['','الكل'],['nz','أرصدة غير صفرية'],['unm','غير مربوط'],['rev','أرصدة عكسية'],['chg','تغير > 25% عن السنة السابقة'],['adj','عليها تسويات']].map(o=>`<option value="${o[0]}"${TBQ.flag===o[0]?' selected':''}>${o[1]}</option>`).join('')}</select></label>
