 const rev=TBSTORE.rows.filter(tbReversed);const big=TBSTORE.rows.filter(r=>pm&&Math.abs(r.cb)>pm&&r.mvDr===0&&r.mvCr===0);const round=TBSTORE.rows.filter(r=>Math.abs(r.cb)>=10000&&Math.abs(r.cb)%1000===0);const nw=TBSTORE.pyMap?TBSTORE.rows.filter(r=>!TBSTORE.pyMap.has(r.code)&&Math.abs(r.cb)>(pm||0)):[];
 const lst=(t,arr,why)=>`<h3>${t} <span class="cnt">${arr.length}</span></h3>${arr.length?`<ul class="lkl">${arr.slice(0,30).map(r=>`<li><a href="${L('tb/acct:'+encodeURIComponent(r.code))}" dir="ltr">${esc(r.code)}</a> ${esc(r.name||r.nameEn)} — <span dir="ltr">${fmtA(r.cb)}</span>${why?' · '+why(r):''}</li>`).join('')}${arr.length>30?`<li class="mut">و${arr.length-30} أخرى…</li>`:''}</ul>`:'<p class="mut small">لا يوجد.</p>'}`;
 const B=benford(TBSTORE.rows.flatMap(r=>[r.mvDr,r.mvCr]));
