const TBNOBIND=new Set(['chk','icq','memo','log','risk','rcm','team','time','plan','idx','sod','auth','uar','itgc','appc','ipe','wt','def','rp','fraud','resp','asm','dsg','kam','op','comp','ic','cons','samp','mus','sens','cf','gw']);
