function wpTbBalance(ref,o){const b=G('wp.'+ref+'.tb',null);if(!b||!TBSTORE.ready())return null;const man=G('wp.'+ref+'.tbman',null);if(man&&man.amount!=null&&!o)return num(man.amount);
 const codes=new Set(b.codes||[]);const lines=b.lines||[];let s=0;for(const r of TBSTORE.rows){if(codes.has(r.code)||(lines.length&&lines.includes(tbMapOf(r.code))))s+=TBSTORE.bal(r,o||{adjusted:!!b.adj})}return r2(s)}
const WPTOTCOL=[/^per gl \/ tb$/i,/^balance per gl$/i,/^per gl$/i,/^amount per gl$/i,/^balance per books$/i,/^balance per cash book$/i,/^cy final$/i,/^closing balance$/i,/^total balance$/i,/^carrying amount$/i,/^client (fair value|amount|charge)$/i,/^per client$/i,/^amount$/i];
function wpGridTotal(ref){const w=WP[ref];if(!w)return null;const cols=gridCols(ref,'m',w);let ci=-1;for(const re of WPTOTCOL){ci=cols.findIndex(c=>re.test(c.trim()));if(ci>-1)break}if(ci<0)return null;const st=CUR.eng;const pf=gridDef(ref,'m',w).pre;let s=0,any=false;
 for(const r of gridRows(st,ref,'m',w)){let v=st.get(`wp.${ref}.g.m.v.${r.id}.${fnv(cols[ci])}`,null);if(v==null&&r.id[0]==='d'){const dd=pf[+r.id.slice(1)];v=dd&&dd[ci]!=null?dd[ci]:null}const n=parseNum(v);if(n!=null&&!isNaN(n)){s+=n;any=true}}return any?{col:cols[ci],sum:r2(s)}.sum:null}
function wpTbCol(ref){const w=WP[ref];if(!w)return null;const cols=gridCols(ref,'m',w);for(const re of WPTOTCOL){const c=cols.find(c=>re.test(c.trim()));if(c)return c}return null}
function tbBindHTML(ref){if(!wpBindable(ref))return '';const ed=can('edit');const b=G('wp.'+ref+'.tb',null);const lines0=wpDefaultLines(ref);
 if(!TBSTORE.ready())return `<div class="card tbbind"><h3 style="margin-top:0">📒 الرصيد من ميزان المراجعة</h3><p class="mut small">${TBSTORE.loading?'جارٍ تحميل الميزان…':`لم يُرفع ميزان مراجعة بعد. <a href="${L('tb/upload')}">رفع الميزان</a>`}</p></div>`;
 const man=G('wp.'+ref+'.tbman',null);const tbv=b?wpTbBalance(ref,{adjusted:!!b.adj}):null;const wt=wpGridTotal(ref);const col=wpTbCol(ref);const stale=b&&b.ver&&b.ver!==TBSTORE.ver;
 const bal=man&&man.amount!=null?num(man.amount):tbv;const diff=bal!=null&&wt!=null?r2(bal-wt):null;
 return `<div class="card tbbind${stale?' stale':''}"><h3 style="margin-top:0">📒 الرصيد من ميزان المراجعة ${stale?`<span class="b bad">قديم — مبني على ميزان v${b.ver}، النشط v${TBSTORE.ver}</span>`:''}</h3>
 ${b?`<p class="stamp small">${esc(TBSTORE.stamp())}${b.at?` · رُبطت ${fmtDT(b.at)} بواسطة ${esc(USERS.nameOf(b.by))}`:''}</p>
 <div class="grid g4"><div class="card kpi"><div class="mut small">الرصيد ${b.adj?'بعد':'قبل'} التسويات</div><b dir="ltr">${fmtA(tbv)}</b></div><div class="card kpi"><div class="mut small">السنة السابقة</div><b dir="ltr">${fmtA(wpTbBalance(ref,{priorYear:true}))}</b></div>
 <div class="card kpi"><div class="mut small">إجمالي ورقة العمل${col?' ('+esc(col)+')':''}</div><b dir="ltr">${wt==null?'—':fmtA(wt)}</b></div><div class="card kpi ${diff===0?'okk':diff!=null?'badk':''}"><div class="mut small">الفرق</div><b dir="ltr">${diff==null?'—':diff===0?'0.00 ✓':fmtA(diff)}</b></div></div>
 <p class="small">الحسابات: ${(b.codes||[]).map(c=>`<a dir="ltr" href="${L('tb/acct:'+encodeURIComponent(c))}">${esc(c)}</a>`).join('، ')||'—'} ${(b.lines||[]).length?' · البنود: '+b.lines.map(l=>esc(AC[l]?AC[l].n:l)).join('، '):''}</p>
 ${man&&man.amount!=null?`<p class="note warn small">رصيد يدوي ${fmtA(num(man.amount))} — المبرر: ${esc(man.reason)} (${esc(USERS.nameOf(man.by))}، ${fmtDT(man.t)}) ${ed?`<button class="btn g sm" type="button" data-act="tbmanclr" data-ref="${esc(ref)}">إلغاء الرصيد اليدوي</button>`:''}</p>`:''}`:`<p class="mut small">اربط هذه الورقة بحسابات الميزان ليُسحب رصيدها آليًا ويُطابق مع إجمالي الورقة.${lines0.length?' البنود المقترحة: '+lines0.map(l=>esc(AC[l].n)).join('، '):''}</p>`}
 ${ed?`<div class="fgrid noprint"><label>إضافة حساب من الميزان${comboHTML({target:'bind:'+ref,label:'إضافة حساب من الميزان'})}</label><label>أو بند قوائم كامل<select class="sel" data-tbbindline="${esc(ref)}"><option value="">—</option>${A.map(a=>`<option value="${a.id}"${lines0.includes(a.id)?' data-sugg="1"':''}>${esc(a.n)}${lines0.includes(a.id)?' ★':''}</option>`).join('')}</select></label>
 <label class="row"><input type="checkbox" data-tbbindadj="${esc(ref)}"${b&&b.adj?' checked':''}> بعد التسويات المعتمدة</label>
 <div class="row">${b?`<button class="btn g sm" type="button" data-act="tbbindclr" data-ref="${esc(ref)}">إلغاء الربط</button>`:''}${stale?`<button class="btn sm" type="button" data-act="tbbindup" data-ref="${esc(ref)}">تحديث إلى v${TBSTORE.ver}</button>`:''}<button class="btn g sm" type="button" data-act="tbman" data-ref="${esc(ref)}">إدخال رصيد يدوي بمبرر</button></div></div>`:''}</div>`}
BLOCKS.tbbind=ref=>tbBindHTML(ref).replace(/^<div class="card tbbind[^"]*">|<\/div>$/g,'');
function tbBindSet(ref,patch){const b=Object.assign({codes:[],lines:[],adj:false},G('wp.'+ref+'.tb',null)||{},patch,{ver:TBSTORE.ver,at:Date.now(),by:SESSION.id});CUR.eng.set('wp.'+ref+'.tb',b,{label:'ربط ورقة العمل بالميزان'});refreshTbBind(ref)}
function refreshTbBind(ref){$$(`[data-tbb="${CSS.escape(ref)}"]`).forEach(el=>{el.innerHTML=tbBindHTML(ref);el.querySelectorAll('textarea').forEach(autogrow)});$$(`[data-lead="${CSS.escape(ref)}"]`).forEach(el=>{el.innerHTML=leadHTML(ref);fitTables(el)})}
/* lead schedule: auto-filled from TB with reconciliation */
const isLead=ref=>WP[ref]&&WP[ref].k==='lead';
function leadLines(ref){if(ref==='V-02'||ref==='Y-01')return A.filter(a=>['A','L','E','P'].includes(a.fs)).map(a=>a.id);const first=A.filter(a=>split(a.wps)[0]===ref).map(a=>a.id);return first.length?first:wpDefaultLines(ref)}
function leadHTML(ref){if(!isLead(ref))return '';if(!TBSTORE.ready())return `<div class="card"><h3 style="margin-top:0">الجدول الرئيسي من الميزان</h3><p class="mut small">${TBSTORE.loading?'جارٍ تحميل الميزان…':`لم يُرفع ميزان مراجعة بعد. <a href="${L('tb/upload')}">رفع الميزان</a>`}</p></div>`;
 const lines=leadLines(ref);const rows=TBSTORE.rows.filter(r=>lines.includes(tbMapOf(r.code)));const adjP=tbAdjMap(CUR.eng,false);const ed=can('edit');let tPY=0,tCY=0,tAJ=0,tF=0;
 const body=rows.map(r=>{const py=TBSTORE.bal(r,{priorYear:true}),aj=adjP.get(r.code)||0,fin=r.cb+aj;tPY+=py;tCY+=r.cb;tAJ+=aj;tF+=fin;const v=fin-py;const k=tbk(r.code);
  return `<tr><td dir="ltr"><a href="${L('tb/acct:'+encodeURIComponent(r.code))}">${esc(r.code)}</a></td><td>${esc(r.name||r.nameEn)}</td><td dir="ltr">${fmtA(py)}</td><td dir="ltr">${fmtA(r.cb)}</td><td dir="ltr">${aj?fmtA(aj):''}</td><td dir="ltr"><b>${fmtA(fin)}</b></td><td dir="ltr">${fmtA(v)}</td><td dir="ltr">${py?(v/Math.abs(py)*100).toFixed(1)+'%':''}</td><td>${edc('wp.'+ref+'.lx.'+k,{label:'تفسير التغير '+r.code})}</td><td>${ed?`<input class="in" data-k="wp.${esc(ref)}.lw.${esc(k)}" value="${esc(G('wp.'+ref+'.lw.'+k,''))}" list="wplist" aria-label="ورقة العمل المؤيدة ${esc(r.code)}">`:esc(G('wp.'+ref+'.lw.'+k,''))}</td></tr>`}).join('');
 const T=TBSTORE.lineTotals({adjusted:true});const lineTot=lines.reduce((s,l)=>s+(T[l]||0),0);const diff=r2(tF-lineTot);
 const sup=lines.flatMap(l=>split(AC[l]?AC[l].wps:'')).filter((x,i,a)=>x!==ref&&a.indexOf(x)===i&&G('wp.'+x+'.tb',null));let supT=0;sup.forEach(x=>{supT+=wpTbBalance(x)||0});
 return `<div class="card"><h3 style="margin-top:0">الجدول الرئيسي من ميزان المراجعة (Lead Schedule) <span class="cnt">${rows.length}</span></h3><p class="stamp small">${esc(TBSTORE.stamp())} · البنود: ${lines.map(l=>esc(AC[l].n)).slice(0,6).join('، ')}${lines.length>6?'…':''}</p>
 ${rows.length?`<div class="tw"><table><thead><tr><th>Account Code</th><th>Account Name</th><th>PY Audited</th><th>CY Unadjusted (TB)</th><th>AJE</th><th>CY Final</th><th>Variance</th><th>Var %</th><th>Explanation of Variance</th><th>Supporting WP</th></tr></thead><tbody>${body}</tbody><tfoot><tr><th colspan="2">الإجمالي</th><td dir="ltr">${fmtA(tPY)}</td><td dir="ltr">${fmtA(tCY)}</td><td dir="ltr">${fmtA(tAJ)}</td><td dir="ltr"><b>${fmtA(tF)}</b></td><td dir="ltr">${fmtA(tF-tPY)}</td><td colspan="3"></td></tr></tfoot></table></div>`:`<p class="mut">لا توجد حسابات مربوطة بهذه البنود. <a href="${L('tb/map')}">ربط الحسابات</a></p>`}
 <div class="kv"><div>مطابقة مع إجمالي البند في الميزان المعدّل</div><div dir="ltr">${fmtA(lineTot)} — ${diff===0?'<b class="ok">الفرق 0 ✓</b>':`<b class="bad">الفرق ${fmtA(diff)}</b>`}</div>
 <div>مطابقة مع أوراق العمل المؤيدة المربوطة (${sup.length})</div><div dir="ltr">${sup.length?`${fmtA(supT)} — ${r2(tF-supT)===0?'<b class="ok">الفرق 0 ✓</b>':`<b class="bad">الفرق ${fmtA(r2(tF-supT))}</b>`} ${wpL(sup.join(' '))}`:'<span class="mut">لا توجد أوراق مؤيدة مربوطة بالميزان بعد.</span>'}</div></div></div>`}
BLOCKS.lead=ref=>leadHTML(ref);
/* materiality from the TB with a log of benchmarks chosen */
function tbBenchmarks(){if(!TBSTORE.ready())return null;const T=TBSTORE.lineTotals({adjusted:true});const g=ids=>ids.reduce((s,i)=>s+(T[i]||0),0);const P=A.filter(a=>a.fs==='P');
 const REV=-g(['rev']),PBT=-g(P.filter(a=>a.id!=='taxx').map(a=>a.id)),TA=g(A.filter(a=>a.fs==='A').map(a=>a.id)),EXP=g(['cos','payx','admx','profx','sellx','depx','eclx','fincost']),EQ=-g(A.filter(a=>a.fs==='E').map(a=>a.id)),GP=REV-g(['cos']);
 return{PBT,REV,EXP,TA,EQ,GP}}
async function tbApplyMateriality(){const bm=G('eng.bm','PBT');const B=tbBenchmarks();if(!B){toast('لا يوجد ميزان مراجعة.','w');return}if(!(bm in B)){toast('هذا المعيار لا يُحسب آليًا من الميزان (متوسط ثلاث سنوات)؛ أدخله يدويًا.','w');return}
 const v=Math.round(Math.abs(B[bm]));CUR.eng.set('eng.bv',String(v),{label:'قيمة المعيار من الميزان'});const log=(G('eng.matlog',[])||[]).slice();log.push({bm,value:v,raw:B[bm],ver:TBSTORE.ver,by:SESSION.id,t:Date.now()});CUR.eng.set('eng.matlog',log,{label:'سجل معايير الأهمية النسبية'});
 const el=$('#mBv');if(el){el.value=String(v);calcAll(true)}toast(`قيمة ${bm} من الميزان v${TBSTORE.ver}: ${fmtN(v)}`,'s');refreshBlock('matlog')}
function matLogHTML(){const log=G('eng.matlog',[])||[];const B=tbBenchmarks();
 return `${B?`<p class="small">من الميزان v${TBSTORE.ver} (بعد التسويات): ${[['PBT','الربح قبل الضريبة'],['REV','الإيرادات'],['GP','مجمل الربح'],['EXP','المصروفات'],['TA','إجمالي الأصول'],['EQ','حقوق الملكية']].map(x=>`${x[1]} <b dir="ltr">${fmtN(B[x[0]])}</b>`).join(' · ')}</p>`:''}
 ${log.length?`<details class="nt"><summary>سجل المعايير المختارة (${log.length})</summary><ul class="lkl">${log.slice().reverse().map(x=>`<li>${fmtDT(x.t)} — ${esc(x.bm)} = <span dir="ltr">${fmtN(x.value)}</span> (ميزان v${x.ver}) — ${esc(USERS.nameOf(x.by))}</li>`).join('')}</ul></details>`:''}`}
BLOCKS.matlog=()=>matLogHTML();
/* exports of the TB view */
function tbExport(fmt){const items=tbFilter().filter(x=>!x.grp);const head=['Account Code','Account Name','Name (EN)','FS Line','Prior Year','Opening','Debit Movement','Credit Movement','Closing (Unadjusted)','Adjustments','Closing (Adjusted)','Branch'];
 const rows=items.map(r=>[r.code,r.name,r.nameEn,AC[tbMapOf(r.code)]?AC[tbMapOf(r.code)].n:'',TBSTORE.bal(r,{priorYear:true}),r.ob,r.mvDr,r.mvCr,r.cb,TBSTORE.adj(r.code),TBSTORE.bal(r,{adjusted:true}),r.branch||'']);const nm=sanitizeName('TB v'+TBSTORE.ver+' - '+CUR.company.name+' '+G('eng.year',''),80);
 if(fmt==='csv'){const q=v=>{v=v==null?'':String(v);return /[",\n;]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v};downloadBlob(new Blob(['﻿'+[head].concat(rows).map(r=>r.map(q).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),nm+'.csv')}
 else downloadBlob(xlsxBlob([{name:'Trial Balance',rows:[head].concat(rows),widths:[14,40,30,30,16,16,16,16,18,14,18,12]}],{title:nm,author:SESSION.display}),nm+'.xlsx');audit('tb.export',{fmt,rows:rows.length})}

function tbAfter(arg){arg=arg||'';if(!TBSTORE.ready())return;if(arg==='cls'){clsAfter();return}if(arg==='')tbMountTable();else if(arg==='map'){tbMountMap();tbCountSugg()}else if(arg==='ver')tbVersionsHTML().then(h=>{const el=$('[data-block="tbver"]');if(el){el.innerHTML=h;fitTables(el)}})}
/* live refresh of TB-dependent blocks when the TB, the mapping or the adjustments change */
TBSTORE.subscribe(()=>{$$('[data-tbb]').forEach(el=>{el.innerHTML=tbBindHTML(el.dataset.tbb)});$$('[data-lead]').forEach(el=>{el.innerHTML=leadHTML(el.dataset.lead);fitTables(el)})});
